// Desktop: intercept `--uninstall-wipe …` before Makepad opens a window
// (MSI / "Delete books data" call this while the exe is still installed).
#[cfg(not(target_os = "android"))]
fn main() {
    if uninstall_wipe::try_run() {
        return;
    }
    desktop_entry::app_main();
}

