/// Nested PortalList inside a page `ScrollYView` — **scroll chaining**
/// (`docs/DEV.md`): the list keeps the wheel only while it can still move
/// that way; at the edge the page takes over (browser behaviour). Claiming
/// Y unconditionally trapped the page whenever the pointer sat on a capped
/// list (Parties, Settings picks, …).
fn claim_list_nested_scroll(cx: &mut Cx, host: &View, event: &Event) {
    let Event::Scroll(e) = event else {
        return;
    };
    let list = host.portal_list(cx, ids!(list));
    let list_area = list.area();
    let area = if list_area.is_valid(cx) {
        list_area
    } else {
        host.area()
    };
    if !area.is_valid(cx) || !area.clipped_rect(cx).contains(e.abs) {
        return;
    }
    let dy = e.scroll.y;
    // PortalList: delta = -scroll → scroll.y > 0 moves toward the end.
    if dy != 0.0 {
        let toward_end = dy > 0.0;
        let can_move = if toward_end {
            !list.is_at_end()
        } else {
            list.first_id() > 0 || list.scroll_position() > 0.5
        };
        if can_move {
            e.handled_y.set(true);
        }
    }
    // Vertical lists do not scroll sideways — leave X for `app_hscroll` /
    // ChipStrip so a diagonal trackpad flick does not freeze the page.
}

/// Horizontal `ScrollXView` (chip / tab strip / bottom nav): claim X only
/// while the strip can still move that way; never claim Y so the page keeps
/// vertical scroll when the pointer is over chips.
fn claim_hstrip_nested_scroll(cx: &mut Cx, strip: &ViewRef, event: &Event) {
    let Event::Scroll(e) = event else {
        return;
    };
    let area = strip.area();
    if !area.is_valid(cx) || !area.clipped_rect(cx).contains(e.abs) {
        return;
    }
    let dx = e.scroll.x;
    if dx == 0.0 {
        return;
    }
    let pos = strip.get_scroll_pos().x;
    let total = strip.get_scroll_view_total().x;
    let seen = strip.get_scroll_view_visible().x;
    let max_x = (total - seen).max(0.0);
    // scroll.x > 0 typically reveals content to the left (pos decreases).
    let toward_left = dx > 0.0;
    let can_move = if toward_left {
        pos > 1.0
    } else {
        pos < max_x - 1.0
    };
    if can_move {
        e.handled_x.set(true);
    }
}

/// Walk the country list one step from `from`, wrapping at both ends. A code
/// that matches nothing (half-typed, say) resumes from the applied pack.
fn step_country(from: &str, step: i64, applied: &str) -> &'static fiscal::CountryProfile {
    let list = fiscal::countries();
    let at = list
        .iter()
        .position(|c| c.code.eq_ignore_ascii_case(from.trim()))
        .or_else(|| {
            list.iter()
                .position(|c| c.code.eq_ignore_ascii_case(applied.trim()))
        })
        .unwrap_or(0) as i64;
    let n = list.len() as i64;
    &list[(((at + step) % n + n) % n) as usize]
}

/// Expand-to-content lists: let the page ScrollYView own wheel/trackpad.
/// Forwarding Scroll into PortalList makes it eat the gesture at the bottom edge
/// so Tea / pay / anything below never comes into view.
fn page_owns_scroll(event: &Event) -> bool {
    matches!(event, Event::Scroll(_))
}

/// Resolve on-disk path for a product/draft image key (custom photo or empty).
fn image_key_path(key: Option<&str>, dir: &std::path::Path) -> std::path::PathBuf {
    match key {
        Some(k) if k.starts_with("pending_custom:") => {
            std::path::PathBuf::from(&k["pending_custom:".len()..])
        }
        Some(k) if k.starts_with("custom:") => dir.join(&k["custom:".len()..]),
        other => menu_images::resolve_image_path(other, "", dir),
    }
}

/// Small display copies of photos live beside the shop's item images.
fn thumb_cache_dir() -> std::path::PathBuf {
    let images = item_images_dir();
    images
        .parent()
        .map(|p| p.join("thumbs"))
        .unwrap_or_else(|| images.join("thumbs"))
}

/// Bind `ThumbAvatar` (`thumb` Image + `thumb_initials` Label).
/// Photo when its small copy is ready; otherwise name initials. Full-size
/// decode is never done on the UI thread — see [`thumbs`].
fn apply_thumb_avatar(cx: &mut Cx, root: &WidgetRef, name: &str, path: &std::path::Path) {
    apply_thumb_avatar_kind(cx, root, name, path, thumbs::ThumbKind::Row);
}

fn apply_thumb_avatar_kind(
    cx: &mut Cx,
    root: &WidgetRef,
    name: &str,
    path: &std::path::Path,
    kind: thumbs::ThumbKind,
) {
    let img = root.image(cx, ids!(thumb));
    let initials_lbl = root.label(cx, ids!(thumb_initials));
    let thumb = if path.as_os_str().is_empty() {
        None
    } else {
        thumbs::cached_or_request_kind(path, &thumb_cache_dir(), kind)
    };
    let has_file = thumb.is_some();
    let queued = thumb
        .as_deref()
        .is_some_and(|small| load_thumb_at(cx, &img, small));
    if has_file {
        img.set_visible(cx, true);
        initials_lbl.set_visible(cx, false);
        initials_lbl.set_text(cx, "");
    } else {
        img.set_visible(cx, false);
        let initials = menu_images::name_initials(name);
        initials_lbl.set_text(cx, &initials);
        initials_lbl.set_visible(cx, !initials.is_empty());
    }
    if queued {
        root.as_view().redraw_texture_cache();
    }
}

fn load_product_thumb(cx: &mut Cx, item: &WidgetRef, product: &Product) {
    let dir = item_images_dir();
    let path = image_key_path(product.image_key.as_deref(), &dir);
    apply_thumb_avatar(cx, item, &product.name, &path);
}

#[derive(Script, ScriptHook, Widget)]
struct ProductList {
    #[deref]
    view: View,
}

impl Widget for ProductList {
    fn draw_walk(&mut self, cx: &mut Cx2d, scope: &mut Scope, walk: Walk) -> DrawStep {
        let (products, currency, fiscal, lang) = {
            let st = app_state().lock().unwrap();
            (
                st.booking_catalog_products(),
                st.locale.currency.clone(),
                st.fiscal.clone(),
                st.locale.language.clone(),
            )
        };
        let rows = products.len().div_ceil(3);
        let row = *product_row_height().lock().unwrap();
        let walk = Walk {
            height: Size::Fixed(list_content_height(rows, row, 0.0)),
            ..walk
        };
        let mut measured_row = 0.0;
        while let Some(step) = self.view.draw_walk(cx, scope, walk).step() {
            if let Some(mut list) = step.as_portal_list().borrow_mut() {
                list.set_item_range(cx, 0, rows);
                while let Some(item_id) = list.next_visible_item(cx) {
                    // PortalList keeps asking for items until the viewport is
                    // filled. Past our row count, drawing a zero-height row
                    // (all cards invisible) never fills it → infinite loop and
                    // OS "app not responding" after unlock shows Sell.
                    if item_id >= rows {
                        continue;
                    }
                    let item = list.item(cx, item_id, id!(Item));
                    for (col, path) in [
                        (0usize, &[id!(c0)][..]),
                        (1, &[id!(c1)][..]),
                        (2, &[id!(c2)][..]),
                    ] {
                        let idx = item_id * 3 + col;
                        let card = item.widget(cx, path);
                        if let Some(product) = products.get(idx) {
                            card.set_visible(cx, true);
                            card.label(cx, ids!(name)).set_text(cx, &product.name);
                            card.label(cx, ids!(price))
                                .set_text(cx, &product.price.format_localized(&currency, &fiscal));
                            load_product_thumb(cx, &card, product);
                            let add = card.button(cx, ids!(add));
                            if product.available {
                                add.set_text(cx, &locale::t(&lang, "add_upper"));
                                add.set_enabled(cx, true);
                            } else {
                                add.set_text(cx, &locale::t(&lang, "na"));
                                add.set_enabled(cx, false);
                            }
                        } else {
                            card.set_visible(cx, false);
                        }
                    }
                    item.draw_all_unscoped(cx);
                }
                if rows > 0 {
                    let extent = list.drawn_range_extent();
                    if extent > 1.0 {
                        measured_row = extent / rows as f64;
                    }
                }
            }
        }
        remember_content_row(cx, &mut self.view, product_row_height(), row, measured_row);
        DrawStep::done()
    }

    fn handle_event(&mut self, cx: &mut Cx, event: &Event, scope: &mut Scope) {
        if page_owns_scroll(event) {
            return;
        }
        self.view.handle_event(cx, event, scope);
    }
}

#[derive(Script, ScriptHook, Widget)]
struct MenuList {
    #[deref]
    view: View,
}

impl Widget for MenuList {
    fn draw_walk(&mut self, cx: &mut Cx2d, scope: &mut Scope, walk: Walk) -> DrawStep {
        let (products, currency, fiscal, lang) = {
            let st = app_state().lock().unwrap();
            (
                st.products.clone(),
                st.locale.currency.clone(),
                st.fiscal.clone(),
                st.locale.language.clone(),
            )
        };
        let count = products.len();
        let row = *menu_row_height().lock().unwrap();
        let walk = Walk {
            height: Size::Fixed(list_content_height(count, row, 0.0)),
            ..walk
        };
        let mut measured_row = 0.0;
        while let Some(step) = self.view.draw_walk(cx, scope, walk).step() {
            if let Some(mut list) = step.as_portal_list().borrow_mut() {
                list.set_item_range(cx, 0, count);
                while let Some(item_id) = list.next_visible_item(cx) {
                    let Some(product) = products.get(item_id) else {
                        continue;
                    };
                    let item = list.item(cx, item_id, id!(Item));
                    item.label(cx, ids!(name)).set_text(cx, &product.name);
                    item.label(cx, ids!(price))
                        .set_text(cx, &product.price.format_localized(&currency, &fiscal));
                    let stock_line = if product.tracks_stock() {
                        format!("{} {}", product.stock_qty, locale::t(&lang, "in_stock"))
                    } else if product.available {
                        locale::t(&lang, "not_tracked")
                    } else {
                        locale::t(&lang, "marked_sold_out")
                    };
                    item.label(cx, ids!(stock)).set_text(cx, &stock_line);
                    load_product_thumb(cx, &item, product);
                    item.button(cx, ids!(sold_out)).set_text(
                        cx,
                        &locale::t(
                            &lang,
                            if product.available {
                                "sold_out"
                            } else {
                                "restock"
                            },
                        ),
                    );
                    item.button(cx, ids!(remove)).set_text(cx, "✕");
                    item.draw_all_unscoped(cx);
                }
                if count > 0 {
                    let extent = list.drawn_range_extent();
                    if extent > 1.0 {
                        measured_row = extent / count as f64;
                    }
                }
            }
        }
        remember_content_row(cx, &mut self.view, menu_row_height(), row, measured_row);
        DrawStep::done()
    }

    fn handle_event(&mut self, cx: &mut Cx, event: &Event, scope: &mut Scope) {
        if page_owns_scroll(event) {
            return;
        }
        self.view.handle_event(cx, event, scope);
    }
}

#[derive(Script, ScriptHook, Widget)]
struct CartList {
    #[deref]
    view: View,
}

impl Widget for CartList {
    fn draw_walk(&mut self, cx: &mut Cx2d, scope: &mut Scope, walk: Walk) -> DrawStep {
        let (lines, products, currency, fiscal, lang) = {
            let st = app_state().lock().unwrap();
            let lines = if st.screen == Screen::Sales {
                st.amend_cart.lines.clone()
            } else {
                st.cart.lines.clone()
            };
            (
                lines,
                st.products.clone(),
                st.locale.currency.clone(),
                st.fiscal.clone(),
                st.locale.language.clone(),
            )
        };
        let count = lines.len();
        let row = *cart_row_height().lock().unwrap();
        let walk = Walk {
            height: Size::Fixed(list_content_height(count, row, 0.0).max(56.0)),
            ..walk
        };
        let mut measured_row = 0.0;
        while let Some(step) = self.view.draw_walk(cx, scope, walk).step() {
            if let Some(mut list) = step.as_portal_list().borrow_mut() {
                list.set_item_range(cx, 0, lines.len());
                while let Some(item_id) = list.next_visible_item(cx) {
                    let Some(line) = lines.get(item_id) else {
                        continue;
                    };
                    let item = list.item(cx, item_id, id!(Item));
                    let actual = line.actual_total();
                    let applied = line.applied_total();
                    let qty_milli = if line.qty_milli > 0 {
                        line.qty_milli
                    } else {
                        line.qty.saturating_mul(1000)
                    };
                    let qty_show = {
                        let whole = qty_milli / 1000;
                        let frac = qty_milli % 1000;
                        let num = if frac == 0 {
                            format!("{whole}")
                        } else {
                            format!("{whole}.{frac:03}")
                                .trim_end_matches('0')
                                .trim_end_matches('.')
                                .to_string()
                        };
                        let unit = line.unit_label.trim();
                        if unit.is_empty() {
                            num
                        } else {
                            format!("{num} {unit}")
                        }
                    };
                    item.widget(cx, ids!(label))
                        .set_text(cx, &plain_display_text(&line.name));
                    item.label(cx, ids!(qty_label)).set_text(cx, &qty_show);
                    item.label(cx, ids!(h_qty_cap))
                        .set_text(cx, &locale::t(&lang, "qty_cap"));
                    item.label(cx, ids!(h_unit_at_cap))
                        .set_text(cx, &locale::t(&lang, "unit_at_cap"));
                    item.label(cx, ids!(h_applied))
                        .set_text(cx, &locale::t(&lang, "applied"));
                    item.text_input(cx, ids!(note))
                        .set_empty_text(cx, locale::t(&lang, "note_ph"));
                    // Actual = @ × qty — always show the real money, never leave ₹0.
                    item.widget(cx, ids!(line_actual_label)).set_text(
                        cx,
                        &plain_display_text(&format!(
                            "{} {}  ({qty_show} × {})",
                            locale::t(&lang, "actual"),
                            actual.format_localized(&currency, &fiscal),
                            line.unit_price.format_localized(&currency, &fiscal)
                        )),
                    );
                    let price_input = item.text_input(cx, ids!(unit_price));
                    if !cx.has_key_focus(price_input.area()) {
                        let price_text = locale::format_major_input_ex(
                            line.unit_price.paise(),
                            &currency,
                            fiscal.decimal_sep(),
                        );
                        if price_input.text() != price_text {
                            price_input.set_text(cx, &price_text);
                        }
                    }
                    let line_total_input = item.text_input(cx, ids!(line_total));
                    // Never rewrite while focused — empty/"0" mid-edit must stay
                    // editable (same rule as unit price / note).
                    if !cx.has_key_focus(line_total_input.area()) {
                        let applied_text = locale::format_major_input_ex(
                            applied.paise(),
                            &currency,
                            fiscal.decimal_sep(),
                        );
                        if line_total_input.text() != applied_text {
                            line_total_input.set_text(cx, &applied_text);
                        }
                    }
                    let note_input = item.text_input(cx, ids!(note));
                    if !cx.has_key_focus(note_input.area()) && note_input.text() != line.note {
                        note_input.set_text(cx, &line.note);
                    }
                    let mods = products
                        .iter()
                        .find(|p| p.id == line.product_id)
                        .map(|p| p.modifiers())
                        .unwrap_or_default();
                    item.view(cx, ids!(mod_row))
                        .set_visible(cx, !mods.is_empty());
                    let pages = mods.len().div_ceil(domain::MODIFIER_PAGE).max(1);
                    let page = line.modifier_page % pages;
                    let start = page * domain::MODIFIER_PAGE;
                    item.button(cx, ids!(mod_prev))
                        .set_visible(cx, mods.len() > domain::MODIFIER_PAGE);
                    item.button(cx, ids!(mod_next))
                        .set_visible(cx, mods.len() > domain::MODIFIER_PAGE);
                    for (slot, path) in [(0, ids!(mod_0)), (1, ids!(mod_1)), (2, ids!(mod_2))] {
                        let button = item.button(cx, path);
                        match mods.get(start + slot) {
                            Some(modifier) => {
                                let on = line
                                    .applied_modifiers
                                    .iter()
                                    .any(|m| m.name == modifier.name);
                                let price = if modifier.price_paise == 0 {
                                    String::new()
                                } else {
                                    format!(
                                        " +{}",
                                        Money(modifier.price_paise)
                                            .format_localized(&currency, &fiscal)
                                    )
                                };
                                let mark = if on { "✓ " } else { "" };
                                button.set_text(cx, &format!("{mark}{}{price}", modifier.name));
                                button.set_visible(cx, true);
                            }
                            None => button.set_visible(cx, false),
                        }
                    }
                    item.draw_all_unscoped(cx);
                }
                if count > 0 {
                    let extent = list.drawn_range_extent();
                    if extent > 1.0 {
                        measured_row = extent / count as f64;
                    }
                }
            }
        }
        remember_content_row(cx, &mut self.view, cart_row_height(), row, measured_row);
        DrawStep::done()
    }

    fn handle_event(&mut self, cx: &mut Cx, event: &Event, scope: &mut Scope) {
        if page_owns_scroll(event) {
            return;
        }
        self.view.handle_event(cx, event, scope);
    }
}

#[derive(Script, ScriptHook, Widget)]
struct SaleList {
    #[deref]
    view: View,
}

impl Widget for SaleList {
    fn draw_walk(&mut self, cx: &mut Cx2d, scope: &mut Scope, walk: Walk) -> DrawStep {
        let (sales, currency, fiscal, lang) = {
            let st = app_state().lock().unwrap();
            (
                st.recent_sales.clone(),
                st.locale.currency.clone(),
                st.fiscal.clone(),
                st.locale.language.clone(),
            )
        };
        let today = chrono::Local::now().format("%Y-%m-%d").to_string();
        let row = *sale_row_height().lock().unwrap();
        let walk = Walk {
            height: Size::Fixed(list_content_height(sales.len(), row, 0.0)),
            ..walk
        };
        let mut measured_row = 0.0;
        while let Some(step) = self.view.draw_walk(cx, scope, walk).step() {
            if let Some(mut list) = step.as_portal_list().borrow_mut() {
                list.set_item_range(cx, 0, sales.len());
                while let Some(item_id) = list.next_visible_item(cx) {
                    let Some(sale) = sales.get(item_id) else {
                        continue;
                    };
                    let item = list.item(cx, item_id, id!(Item));
                    let money = |paise: i64| Money(paise).format_localized(&currency, &fiscal);
                    let method = match sale.pay_method.as_str() {
                        "cash" => locale::t(&lang, "cash"),
                        "upi" => fiscal.digital_pay_label().to_string(),
                        "card" => locale::t(&lang, "card"),
                        "credit" => locale::t(&lang, "pay_credit"),
                        "split" => locale::t(&lang, "split"),
                        other => other.to_string(),
                    };
                    // "AWB-… · Rajkot", or how it was paid when there is no AWB.
                    let main = match (sale.awb_no.trim(), sale.destination.trim()) {
                        ("", _) => method.clone(),
                        (awb, "") => awb.to_string(),
                        (awb, to) => format!("{awb} · {to}"),
                    };
                    // "13:00" today, "2026-10-21 19:05" before; how paid; by
                    // whom; the status only when it is not an ordinary one.
                    let at = sale.created_at.replace('T', " ");
                    let mut sub = if at.get(..10) == Some(today.as_str()) {
                        at.get(11..16).unwrap_or("").to_string()
                    } else {
                        at.get(..16).unwrap_or(&at).to_string()
                    };
                    if !sale.awb_no.trim().is_empty() {
                        sub.push_str(&format!(" · {method}"));
                    }
                    if !sale.created_by_name.is_empty() {
                        sub.push_str(&format!(" · {}", sale.created_by_name));
                    }
                    if sale.status != "completed" {
                        sub.push_str(&format!(" · {}", sale.status));
                    }
                    if sale.rounding_paise != 0 {
                        sub.push_str(&format!(
                            " · Applied {} · round {}",
                            money(sale.lines_total_paise),
                            money(sale.rounding_paise)
                        ));
                    }
                    item.label(cx, ids!(sale_main)).set_text(cx, &main);
                    item.label(cx, ids!(label)).set_text(cx, &sub);
                    item.label(cx, ids!(sale_amount)).set_text(cx, &money(sale.total_paise));
                    item.draw_all_unscoped(cx);
                }
                if !sales.is_empty() {
                    let extent = list.drawn_range_extent();
                    if extent > 1.0 {
                        measured_row = extent / sales.len() as f64;
                    }
                }
            }
        }
        remember_content_row(cx, &mut self.view, sale_row_height(), row, measured_row);
        DrawStep::done()
    }

    fn handle_event(&mut self, cx: &mut Cx, event: &Event, scope: &mut Scope) {
        if page_owns_scroll(event) {
            return;
        }
        self.view.handle_event(cx, event, scope);
    }
}

/// Under a "type or pick" field (see `suggest.rs`): closed it draws
/// nothing; open it is a capped scrolling list of what the counter
/// already has for that field. `field` names which [`SuggestField`] it serves.
#[derive(Script, ScriptHook, Widget)]
struct SuggestList {
    #[deref]
    view: View,
    #[live]
    field: String,
    #[rust]
    drawn_rev: u64,
}

impl SuggestList {
    fn is_open(&self) -> bool {
        app_state().lock().unwrap().suggest_open.map(|f| f.key()) == Some(self.field.as_str())
    }
}

impl Widget for SuggestList {
    fn draw_walk(&mut self, cx: &mut Cx2d, scope: &mut Scope, walk: Walk) -> DrawStep {
        let (open, rows, rev, lang) = {
            let st = app_state().lock().unwrap();
            (
                st.suggest_open.map(|f| f.key()) == Some(self.field.as_str()),
                st.suggest_rows.clone(),
                st.suggest_rev,
                st.locale.language.clone(),
            )
        };
        if !open || rows.is_empty() {
            return DrawStep::done();
        }
        let walk = Walk {
            height: Size::Fixed(list_content_height(rows.len(), 51.0, 4.0).min(SUGGEST_MAX_HEIGHT)),
            ..walk
        };
        let use_text = locale::t(&lang, "use");
        let new_rev = self.drawn_rev != rev;
        while let Some(step) = self.view.draw_walk(cx, scope, walk).step() {
            if let Some(mut list) = step.as_portal_list().borrow_mut() {
                if new_rev {
                    list.set_first_id_and_scroll(0, 0.0);
                }
                list.set_item_range(cx, 0, rows.len());
                while let Some(item_id) = list.next_visible_item(cx) {
                    let Some(row) = rows.get(item_id) else {
                        continue;
                    };
                    let item = list.item(cx, item_id, id!(Item));
                    item.label(cx, ids!(title)).set_text(cx, &row.value);
                    item.label(cx, ids!(subtitle)).set_text(cx, &row.subtitle);
                    item.label(cx, ids!(subtitle)).set_visible(cx, !row.subtitle.is_empty());
                    let action = if row.action.trim().is_empty() {
                        use_text.as_str()
                    } else {
                        row.action.as_str()
                    };
                    item.label(cx, ids!(action)).set_text(cx, action);
                    item.draw_all_unscoped(cx);
                }
            }
        }
        self.drawn_rev = rev;
        DrawStep::done()
    }

    fn handle_event(&mut self, cx: &mut Cx, event: &Event, scope: &mut Scope) {
        if !self.is_open() {
            return;
        }
        claim_list_nested_scroll(cx, &self.view, event);
        self.view.handle_event(cx, event, scope);
        claim_list_nested_scroll(cx, &self.view, event);
    }
}

/// Tallest a "type or pick" list gets before it scrolls (about six rows).
const SUGGEST_MAX_HEIGHT: f64 = 330.0;

#[derive(Script, ScriptHook, Widget)]
struct CustomerList {
    #[deref]
    view: View,
}

impl Widget for CustomerList {
    fn draw_walk(&mut self, cx: &mut Cx2d, scope: &mut Scope, walk: Walk) -> DrawStep {
        let (customers, currency, fiscal, selected_id, lang) = {
            let st = app_state().lock().unwrap();
            (
                st.customers.clone(),
                st.locale.currency.clone(),
                st.fiscal.clone(),
                st.selected_customer_id.clone(),
                st.locale.language.clone(),
            )
        };
        // Full content height + page scroll (SaleList rule). A 3-row capped
        // nested PortalList kept an inner scroll offset → blank gap under
        // "Saved parties" with rows stuck at the bottom of the viewport.
        let row = *customer_row_height().lock().unwrap();
        let n = customers.len();
        let walk = Walk {
            height: Size::Fixed(list_content_height(n, row, 0.0)),
            ..walk
        };
        let mut measured_row = 0.0;
        while let Some(step) = self.view.draw_walk(cx, scope, walk).step() {
            if let Some(mut list) = step.as_portal_list().borrow_mut() {
                list.set_item_range(cx, 0, n);
                while let Some(item_id) = list.next_visible_item(cx) {
                    let Some(c) = customers.get(item_id) else {
                        continue;
                    };
                    let item = list.item(cx, item_id, id!(Item));
                    let is_selected = selected_id.as_deref() == Some(c.id.as_str());
                    let mark = if is_selected { "✓ " } else { "" };
                    let role = c.kind_label.trim();
                    let name_bit = if role.is_empty() {
                        c.name.clone()
                    } else {
                        format!("{} · {}", c.name, role)
                    };
                    let text = if c.balance_paise > 0 {
                        format!(
                            "{}{} · {} {}",
                            mark,
                            name_bit,
                            locale::t(&lang, "owes_word"),
                            Money(c.balance_paise).format_localized(&currency, &fiscal)
                        )
                    } else if c.balance_paise < 0 {
                        format!(
                            "{}{} · {} {}",
                            mark,
                            name_bit,
                            locale::t(&lang, "advance"),
                            Money(-c.balance_paise).format_localized(&currency, &fiscal)
                        )
                    } else {
                        format!("{}{}", mark, name_bit)
                    };
                    // Khaynjo practise: WrapLabel via widget() + plain_display_text
                    // (Markdown escapes). `.label()` on WrapLabel drew blank rows.
                    item.widget(cx, ids!(label))
                        .set_text(cx, &plain_display_text(&text));
                    let phone = c.phone.trim();
                    let addr = c.address.trim();
                    let sub = match (phone.is_empty(), addr.is_empty()) {
                        (true, true) => String::new(),
                        (false, true) => phone.to_string(),
                        (true, false) => addr.to_string(),
                        (false, false) => format!("{phone} · {addr}"),
                    };
                    item.widget(cx, ids!(sublabel))
                        .set_text(cx, &plain_display_text(&sub));
                    let dir = party_images_dir();
                    let path = if c.image_key.trim().is_empty() {
                        std::path::PathBuf::new()
                    } else {
                        image_key_path(Some(c.image_key.as_str()), &dir)
                    };
                    apply_thumb_avatar(cx, &item, &c.name, &path);
                    let pick_text = if is_selected {
                        locale::t(&lang, "selected_word")
                    } else {
                        locale::t(&lang, "pick")
                    };
                    item.button(cx, ids!(pick)).set_text(cx, &pick_text);
                    item.draw_all_unscoped(cx);
                }
                if n > 0 {
                    let extent = list.drawn_range_extent();
                    if extent > 1.0 {
                        measured_row = extent / n as f64;
                    }
                }
            }
        }
        remember_content_row(cx, &mut self.view, customer_row_height(), row, measured_row);
        DrawStep::done()
    }

    fn handle_event(&mut self, cx: &mut Cx, event: &Event, scope: &mut Scope) {
        if page_owns_scroll(event) {
            return;
        }
        self.view.handle_event(cx, event, scope);
    }
}

