    /// Settings → Sidebar: pill toggles + Enable/Disable All.
    fn handle_sidebar_nav_list_actions(&mut self, cx: &mut Cx, actions: &Actions) {
        if app_state().lock().unwrap().screen != Screen::SidebarSettings {
            return;
        }
        if self.ui.button(cx, ids!(sidebar_enable_all)).clicked(actions) {
            self.set_all_sidebar_visibility(cx, true);
            return;
        }
        if self.ui.button(cx, ids!(sidebar_disable_all)).clicked(actions) {
            self.set_all_sidebar_visibility(cx, false);
            return;
        }
        let widget = self.ui.widget(cx, ids!(sidebar_nav_list));
        // A drag-reorder release over a toggle must not also flip visibility.
        let suppress = widget
            .as_sidebar_nav_list()
            .borrow()
            .map(|w| w.suppress_face_click)
            .unwrap_or(false);
        if suppress {
            if let Some(mut w) = widget.as_sidebar_nav_list().borrow_mut() {
                w.suppress_face_click = false;
            }
            return;
        }
        let list = widget.portal_list(cx, ids!(list));
        let order_len = app_state().lock().unwrap().nav_order.len();
        let mut changed_vis = false;
        for (item_id, item) in list.items_with_actions(actions) {
            if item_id >= order_len {
                continue;
            }
            if !item.button(cx, ids!(toggle_hit)).clicked(actions) {
                continue;
            }
            let mut st = app_state().lock().unwrap();
            let tab = st.nav_order[item_id];
            if nav_tab_always_visible(tab) {
                continue;
            }
            if let Some(i) = st.nav_hidden.iter().position(|t| *t == tab) {
                st.nav_hidden.remove(i);
            } else {
                st.nav_hidden.push(tab);
            }
            if let Some(store) = st.store.as_ref() {
                let _ = store.set_nav_hidden_csv(&nav_hidden_csv(&st.nav_hidden));
            }
            changed_vis = true;
            break;
        }
        if changed_vis {
            let msg = app_state().lock().unwrap().t("sidebar_visibility_saved");
            self.set_status(cx, msg);
            self.sync_chrome(cx);
        }
    }

    /// Show or hide every chrome peer that is allowed to toggle
    /// (Settings and Lock stay on the bar).
    fn set_all_sidebar_visibility(&mut self, cx: &mut Cx, enable: bool) {
        {
            let mut st = app_state().lock().unwrap();
            st.nav_hidden = if enable {
                Vec::new()
            } else {
                NAV_TABS
                    .iter()
                    .copied()
                    .filter(|t| !nav_tab_always_visible(*t))
                    .collect()
            };
            if let Some(store) = st.store.as_ref() {
                let _ = store.set_nav_hidden_csv(&nav_hidden_csv(&st.nav_hidden));
            }
        }
        let msg = app_state().lock().unwrap().t("sidebar_visibility_saved");
        self.set_status(cx, msg);
        self.sync_chrome(cx);
    }

    /// Display label a nav slot wears for `tab` (same strings as the
    /// chrome paint in paint_chrome).
    fn nav_tab_label(&self, tab: NavTab) -> String {
        let lang = app_state().lock().unwrap().locale.language.clone();
        let s = |key: &str| locale::t(&lang, key);
        match tab {
            NavTab::Books => s("books"),
            NavTab::Sell => s("sell"),
            NavTab::Buy => s("buy"),
            NavTab::Rates => s("items"),
            NavTab::Ops => "Ops".to_string(),
            NavTab::Cod => "COD".to_string(),
            NavTab::Riders => s("riders"),
            NavTab::Sales => s("sales"),
            NavTab::DayClose => s("day_close"),
            NavTab::Reports => s("nav_reports"),
            NavTab::Inventory => s("inventory"),
            NavTab::Branches => s("branches"),
            NavTab::Credit => s("credit"),
            NavTab::Team => s("team"),
            NavTab::Settings => s("nav_settings"),
            NavTab::Lock => s("nav_lock"),
        }
    }

    /// Rect of the face currently drawn for `slot` (idle or active).
    fn nav_slot_rect(&mut self, cx: &mut Cx, rail: bool, slot: usize) -> Option<Rect> {
        let pairs = if rail {
            self.rail_nav_pairs()
        } else {
            self.bottom_nav_pairs()
        };
        let (idle, on) = pairs[slot];
        for face in [idle, on] {
            let rect = self.ui.button(cx, face).area().rect(cx);
            if rect.size.x > 0.0 && rect.size.y > 0.0 {
                return Some(Rect {
                    pos: DVec2 {
                        x: rect.pos.x,
                        y: rect.pos.y,
                    },
                    size: rect.size,
                });
            }
        }
        None
    }

    fn place_nav_ghost(&mut self, cx: &mut Cx, pos: DVec2) {
        let ghost = self.ui.widget(cx, ids!(nav_drag_ghost));
        if let Some(mut view) = ghost.borrow_mut::<View>() {
            view.walk.abs_pos = Some(pos);
        }
        ghost.redraw(cx);
    }

    fn show_nav_ghost(&mut self, cx: &mut Cx, tab: NavTab, pos: DVec2) {
        let label = nav_tab_caption(tab, &self.nav_tab_label(tab));
        self.ui
            .widget(cx, ids!(nav_drag_ghost_label))
            .set_text(cx, &label);
        load_nav_icon_once(cx, &self.ui.image(cx, ids!(nav_drag_ghost_icon)), tab);
        self.place_nav_ghost(cx, pos);
        self.ui.view(cx, ids!(nav_drag_ghost)).set_visible(cx, true);
        // The ghost lives in a Modal so it paints on the overlay draw
        // list, above every scroll view (rail, page, bottom bar alike).
        self.ui.modal(cx, ids!(nav_drag_modal)).open(cx);
        cx.redraw_all();
    }

    fn hide_nav_ghost(&mut self, cx: &mut Cx) {
        self.ui.modal(cx, ids!(nav_drag_modal)).close(cx);
        self.ui
            .view(cx, ids!(nav_drag_ghost))
            .set_visible(cx, false);
    }

    /// Settings → Sidebar list: same ghost-chip drag as the rail/bottom
    /// bar. Press on a row, move past the threshold → floating chip with
    /// icon+name; drop on another row to swap. Tap (no move) still
    /// toggles show/hide via the face button.
    fn pointer_sidebar_settings_drag(&mut self, cx: &mut Cx, event: &Event) -> bool {
        match event {
            Event::MouseDown(e) if e.button.is_primary() => {
                *settings_nav_drag().lock().unwrap() = None;
                if app_state().lock().unwrap().screen != Screen::SidebarSettings {
                    return false;
                }
                // Press on the in-row toggle is a flip, not a reorder.
                if self.sidebar_settings_press_on_toggle(cx, e.abs) {
                    return false;
                }
                if let Some(slot) = self.sidebar_settings_slot_at(cx, e.abs) {
                    *nav_drag().lock().unwrap() = None;
                    self.hide_nav_ghost(cx);
                    let origin = self
                        .sidebar_settings_row_rect(cx, slot)
                        .map(|rect| rect.pos)
                        .unwrap_or(e.abs);
                    let scroll = self
                        .ui
                        .view(cx, ids!(sidebar_settings_screen))
                        .get_scroll_pos();
                    let n = app_state().lock().unwrap().nav_order.len();
                    let mut rects = Vec::with_capacity(n);
                    for i in 0..n {
                        let mut found = Rect::default();
                        if let Some(rect) = self.sidebar_settings_row_rect(cx, i) {
                            found = Rect {
                                pos: DVec2 {
                                    x: rect.pos.x + scroll.x,
                                    y: rect.pos.y + scroll.y,
                                },
                                size: rect.size,
                            };
                        }
                        rects.push(found);
                    }
                    *settings_nav_drag().lock().unwrap() = Some(SettingsNavDrag {
                        slot,
                        start: e.abs,
                        last: e.abs,
                        origin,
                        rects,
                        active: false,
                        hover: Some(slot),
                    });
                }
                false
            }
            Event::MouseMove(e) => {
                let mut active = false;
                let mut ghost: Option<(bool, NavTab, DVec2)> = None;
                let mut suppress_list = false;
                {
                    let mut guard = settings_nav_drag().lock().unwrap();
                    if let Some(d) = guard.as_mut() {
                        let was_active = d.active;
                        if !d.active && (e.abs - d.start).length() > 10.0 {
                            d.active = true;
                            suppress_list = true;
                        }
                        if d.active {
                            active = true;
                            d.last = e.abs;
                            d.hover = self.sidebar_settings_drop_slot(cx, d, e.abs);
                            let tab = {
                                app_state()
                                    .lock()
                                    .unwrap()
                                    .nav_order
                                    .get(d.slot)
                                    .copied()
                            };
                            if let Some(tab) = tab {
                                ghost = Some((!was_active, tab, d.origin + (e.abs - d.start)));
                            }
                        }
                    }
                }
                if suppress_list {
                    let widget = self.ui.widget(cx, ids!(sidebar_nav_list));
                    if let Some(mut w) = widget.as_sidebar_nav_list().borrow_mut() {
                        w.suppress_face_click = true;
                    }
                }
                if active {
                    cx.set_cursor(MouseCursor::Grabbing);
                }
                if let Some((first, tab, pos)) = ghost {
                    if first {
                        self.show_nav_ghost(cx, tab, pos);
                    } else {
                        self.place_nav_ghost(cx, pos);
                    }
                }
                active
            }
            Event::MouseUp(e) if e.button.is_primary() => {
                let taken = { settings_nav_drag().lock().unwrap().take() };
                if let Some(d) = taken {
                    self.hide_nav_ghost(cx);
                    if d.active {
                        cx.set_cursor(MouseCursor::Default);
                        let swapped = match d.hover {
                            Some(target) if target != d.slot => {
                                let mut st = app_state().lock().unwrap();
                                if d.slot < st.nav_order.len() && target < st.nav_order.len() {
                                    st.nav_order.swap(d.slot, target);
                                    if let Some(store) = st.store.as_ref() {
                                        let _ =
                                            store.set_nav_order_csv(&nav_order_csv(&st.nav_order));
                                    }
                                    true
                                } else {
                                    false
                                }
                            }
                            _ => false,
                        };
                        if swapped {
                            let msg = app_state().lock().unwrap().t("sidebar_order_saved");
                            self.set_status(cx, msg);
                            self.sync_chrome(cx);
                        }
                        return true;
                    }
                }
                false
            }
            _ => false,
        }
    }

    fn sidebar_settings_row_rect(&mut self, cx: &mut Cx, index: usize) -> Option<Rect> {
        let list = self
            .ui
            .widget(cx, ids!(sidebar_nav_list))
            .portal_list(cx, ids!(list));
        let item = list.item(cx, index, id!(Item));
        let rect = item.button(cx, ids!(face)).area().rect(cx);
        if rect.size.x > 0.0 && rect.size.y > 0.0 {
            Some(rect)
        } else {
            None
        }
    }

    fn sidebar_settings_press_on_toggle(&mut self, cx: &mut Cx, abs: DVec2) -> bool {
        let list = self
            .ui
            .widget(cx, ids!(sidebar_nav_list))
            .portal_list(cx, ids!(list));
        let n = app_state().lock().unwrap().nav_order.len();
        for i in 0..n {
            let item = list.item(cx, i, id!(Item));
            let rect = item.button(cx, ids!(toggle_hit)).area().rect(cx);
            if rect.size.x > 0.0 && rect.size.y > 0.0 && rect.contains(abs) {
                return true;
            }
        }
        false
    }

    fn sidebar_settings_slot_at(&mut self, cx: &mut Cx, abs: DVec2) -> Option<usize> {
        let n = app_state().lock().unwrap().nav_order.len();
        for i in 0..n {
            if let Some(rect) = self.sidebar_settings_row_rect(cx, i) {
                if rect.contains(abs) {
                    return Some(i);
                }
            }
        }
        None
    }

    fn sidebar_settings_drop_slot(
        &mut self,
        cx: &mut Cx,
        drag: &SettingsNavDrag,
        pos: DVec2,
    ) -> Option<usize> {
        let scroll = self
            .ui
            .view(cx, ids!(sidebar_settings_screen))
            .get_scroll_pos();
        let pos = DVec2 {
            x: pos.x + scroll.x,
            y: pos.y + scroll.y,
        };
        let mut first_rect: Option<Rect> = None;
        let mut last_rect: Option<Rect> = None;
        for (slot, rect) in drag.rects.iter().enumerate() {
            if rect.size.x <= 0.0 || rect.size.y <= 0.0 {
                continue;
            }
            if first_rect.is_none() {
                first_rect = Some(*rect);
            }
            last_rect = Some(*rect);
            let hit = pos.x >= rect.pos.x - 2.0
                && pos.x <= rect.pos.x + rect.size.x + 2.0
                && pos.y >= rect.pos.y - 5.0
                && pos.y <= rect.pos.y + rect.size.y + 5.0;
            if hit {
                return Some(slot);
            }
        }
        if let (Some(first), Some(last)) = (first_rect, last_rect) {
            let last_slot = drag.rects.len() - 1;
            let in_band = pos.x >= first.pos.x - 28.0 && pos.x <= first.pos.x + first.size.x + 28.0;
            if in_band && pos.y >= last.pos.y + last.size.y {
                return Some(last_slot);
            }
            if in_band && pos.y <= first.pos.y {
                return Some(0);
            }
        }
        None
    }

    /// Drag a sidebar / bottom-bar item onto another one to swap them.
    /// Scroll and drag are separated spatially, not by timing: the bars
    /// keep whitespace lanes around the items (padding and gaps inside
    /// the scroll view), so a press on whitespace belongs to the scroll
    /// view and never reaches this peek — it starts only when the press
    /// lands on an item. From an item, a plain click navigates and any
    /// real movement picks the item up; from then on the drag owns the
    /// gesture so the scroll view cannot scroll the drop target away
    /// mid-drag. The new arrangement is saved into the books, so it
    /// survives reinstall.
    /// Returns true when the event was consumed by the drag.
    fn pointer_nav_drag(&mut self, cx: &mut Cx, event: &Event) -> bool {
        match event {
            Event::MouseDown(e) if e.button.is_primary() => {
                *nav_drag().lock().unwrap() = None;
                // Do not clear settings_nav_drag here — that peek runs
                // first and may have just armed a press on the list.
                // A fresh press starts a fresh gesture — never let a
                // leftover scroll-suppression eat this tap.
                *nav_suppress_click().lock().unwrap() = false;
                // Only hide the ghost when this press is not already a
                // settings-list arm (otherwise we'd flash the chip away).
                if settings_nav_drag().lock().unwrap().is_none() {
                    self.hide_nav_ghost(cx);
                }
                let unlocked = {
                    let st = app_state().lock().unwrap();
                    !matches!(
                        st.screen,
                        Screen::Lock | Screen::DeviceSetup | Screen::Onboard | Screen::ClientPair
                    )
                };
                if !unlocked {
                    return false;
                }
                // Only the visible surface can be dragged (mirrors
                // apply_shell_layout's rail-vs-bottom choice).
                let shell_wide =
                    self.window_inner_width(cx) >= store::TABLET_SHELL_BREAKPOINT_CSS;
                let rail_collapsed = app_state().lock().unwrap().rail_collapsed;
                if shell_wide && rail_collapsed {
                    return false;
                }
                let rail = shell_wide;
                // The rail divider owns its own drag (resize) — stay out of it.
                if rail {
                    let rail_w = app_state().lock().unwrap().rail_width;
                    if e.abs.x >= rail_w - 2.0 && e.abs.x <= rail_w + 14.0 {
                        return false;
                    }
                }
                if let Some(slot) = self.nav_slot_at(cx, rail, e.abs, 0.0, 0.0) {
                    *settings_nav_drag().lock().unwrap() = None;
                    self.hide_nav_ghost(cx);
                    let origin = self
                        .nav_slot_rect(cx, rail, slot)
                        .map(|rect| rect.pos)
                        .unwrap_or(e.abs);
                    // Freeze every slot's rect in content coordinates
                    // (drawn rect + scroll right now, while settled);
                    // drag-time hit tests use these, not live areas.
                    let scroll = if rail {
                        self.ui.view(cx, ids!(rail_scroll)).get_scroll_pos()
                    } else {
                        self.ui.view(cx, ids!(bottom_nav_scroll)).get_scroll_pos()
                    };
                    let pairs = if rail {
                        self.rail_nav_pairs()
                    } else {
                        self.bottom_nav_pairs()
                    };
                    let mut rects = Vec::with_capacity(pairs.len());
                    for (idle, on) in &pairs {
                        let mut found = Rect::default();
                        for face in [idle, on] {
                            let rect = self.ui.button(cx, face).area().rect(cx);
                            if rect.size.x > 0.0 && rect.size.y > 0.0 {
                                found = Rect {
                                    pos: DVec2 {
                                        x: rect.pos.x + scroll.x,
                                        y: rect.pos.y + scroll.y,
                                    },
                                    size: rect.size,
                                };
                                break;
                            }
                        }
                        rects.push(found);
                    }
                    *nav_drag().lock().unwrap() = Some(NavDrag {
                        rail,
                        slot,
                        start: e.abs,
                        last: e.abs,
                        origin,
                        rects,
                        active: false,
                        hover: Some(slot),
                    });
                }
                false
            }
            Event::MouseMove(e) => {
                let mut repaint = false;
                let mut active = false;
                let mut ghost: Option<(bool, NavTab, DVec2)> = None;
                {
                    let mut guard = nav_drag().lock().unwrap();
                    if let Some(d) = guard.as_mut() {
                        let was_active = d.active;
                        if !d.active && (e.abs - d.start).length() > 10.0 {
                            d.active = true;
                        }
                        if d.active {
                            active = true;
                            d.last = e.abs;
                            if !was_active {
                                // Start the per-frame edge auto-scroll
                                // loop for this drag.
                                *nav_autoscroll_frame().lock().unwrap() = Some(cx.new_next_frame());
                            }
                            let hover = self.nav_drop_slot(cx, d, e.abs);
                            if hover != d.hover {
                                d.hover = hover;
                                repaint = true;
                            }
                            let tab = {
                                let st = app_state().lock().unwrap();
                                nav_display_order(&st.nav_order, &st.nav_hidden)
                                    .get(d.slot)
                                    .copied()
                            };
                            if let Some(tab) = tab {
                                ghost = Some((!was_active, tab, d.origin + (e.abs - d.start)));
                            }
                        }
                    }
                }
                if active {
                    // Drag icon for the whole drag — the button's Hand
                    // hover cursor would otherwise stay on screen.
                    cx.set_cursor(MouseCursor::Grabbing);
                }
                if let Some((first, tab, pos)) = ghost {
                    if first {
                        self.show_nav_ghost(cx, tab, pos);
                    } else {
                        self.place_nav_ghost(cx, pos);
                    }
                }
                if repaint {
                    self.repaint_nav_tabs(cx);
                }
                active
            }
            Event::MouseUp(e) if e.button.is_primary() => {
                // Take in its own scope: an `if let` scrutinee guard would
                // stay locked across the block and deadlock the repaint
                // below (paint_nav_tabs reads the same mutex).
                let taken = { nav_drag().lock().unwrap().take() };
                if let Some(d) = taken {
                    self.hide_nav_ghost(cx);
                    if d.active {
                        // Drag over: back to the nav button's pointer when
                        // still over a slot, plain arrow anywhere else.
                        cx.set_cursor(if d.hover.is_some() {
                            MouseCursor::Hand
                        } else {
                            MouseCursor::Default
                        });
                        let swapped = match d.hover {
                            Some(target) if target != d.slot => {
                                let mut st = app_state().lock().unwrap();
                                let disp = nav_display_order(&st.nav_order, &st.nav_hidden);
                                let Some(ta) = disp.get(d.slot).copied() else {
                                    return true;
                                };
                                let Some(tb) = disp.get(target).copied() else {
                                    return true;
                                };
                                let Some(ia) = st.nav_order.iter().position(|t| *t == ta) else {
                                    return true;
                                };
                                let Some(ib) = st.nav_order.iter().position(|t| *t == tb) else {
                                    return true;
                                };
                                st.nav_order.swap(ia, ib);
                                if let Some(store) = st.store.as_ref() {
                                    let _ = store.set_nav_order_csv(&nav_order_csv(&st.nav_order));
                                }
                                true
                            }
                            _ => false,
                        };
                        if swapped {
                            self.set_status(cx, "Menu order saved");
                        }
                        // The release is consumed, so no Button click is
                        // generated — nothing to suppress afterwards.
                        *nav_suppress_click().lock().unwrap() = false;
                        self.sync_chrome(cx);
                        return true;
                    }
                }
                false
            }
            _ => false,
        }
    }

    /// Edge auto-scroll, one call per frame while a nav drag is live:
    /// holding the dragged item against the bar's edge scrolls the bar
    /// underneath the stationary pointer — gently at the edge zone's
    /// border, faster the deeper the pointer sits in it — so an item
    /// that was off-screen when the drag began can still be reached
    /// and swapped with. The drop target is recomputed after every
    /// step, because the items just slid under the pointer.
    fn nav_drag_autoscroll(&mut self, cx: &mut Cx) {
        let (rail, last) = {
            let guard = nav_drag().lock().unwrap();
            match guard.as_ref() {
                Some(d) if d.active => (d.rail, d.last),
                _ => return, // drag over: let the frame loop die
            }
        };
        // Keep the loop alive for the whole drag.
        *nav_autoscroll_frame().lock().unwrap() = Some(cx.new_next_frame());
        let view = if rail {
            self.ui.view(cx, ids!(rail_scroll))
        } else {
            self.ui.view(cx, ids!(bottom_nav_scroll))
        };
        let rect = view.area().rect(cx);
        if rect.size.x <= 0.0 || rect.size.y <= 0.0 {
            return;
        }
        const ZONE: f64 = 56.0;
        let (near_start, near_end) = if rail {
            (
                (ZONE - (last.y - rect.pos.y)).clamp(0.0, ZONE),
                (ZONE - (rect.pos.y + rect.size.y - last.y)).clamp(0.0, ZONE),
            )
        } else {
            (
                (ZONE - (last.x - rect.pos.x)).clamp(0.0, ZONE),
                (ZONE - (rect.pos.x + rect.size.x - last.x)).clamp(0.0, ZONE),
            )
        };
        let step = |depth: f64| {
            if depth > 0.0 {
                2.0 + depth / ZONE * 10.0
            } else {
                0.0
            }
        };
        let delta = step(near_end) - step(near_start);
        if delta == 0.0 {
            return;
        }
        let cur = view.get_scroll_pos();
        let total = view.get_scroll_view_total();
        let visible = view.get_scroll_view_visible();
        let mut next = cur;
        if rail {
            next.y = (cur.y + delta).clamp(0.0, (total.y - visible.y).max(0.0));
        } else {
            next.x = (cur.x + delta).clamp(0.0, (total.x - visible.x).max(0.0));
        }
        if next.x == cur.x && next.y == cur.y {
            return; // already at the scroll end
        }
        view.set_scroll_pos(cx, next);
        let mut repaint = false;
        {
            let mut guard = nav_drag().lock().unwrap();
            if let Some(d) = guard.as_mut() {
                let hover = self.nav_drop_slot(cx, d, d.last);
                if hover != d.hover {
                    d.hover = hover;
                    repaint = true;
                }
            }
        }
        if repaint {
            self.repaint_nav_tabs(cx);
        }
    }

    /// Mouse Back/Forward, left-edge swipe → back, right-edge swipe → forward.
    /// TouchUpdate on phones; primary MouseDown/Up edge drag on desktop.
    /// Top-level peers do not keep history, so Back/swipe is a no-op there
    /// (except dismissing the soft keyboard).
    fn pointer_navigates(&mut self, cx: &mut Cx, event: &Event) -> bool {
        if self.pointer_rail_resize(cx, event) {
            return true;
        }
        let navigated = match event {
            Event::MouseDown(e) if e.button.is_back() => {
                *mouse_swipe_origin().lock().unwrap() = None;
                self.navigate_back(cx)
            }
            Event::MouseDown(e) if e.button.is_forward() => {
                *mouse_swipe_origin().lock().unwrap() = None;
                self.navigate_forward(cx)
            }
            Event::MouseDown(e) if e.button.is_primary() => {
                // Skip edge-swipe arming while the rail is showing — left edge
                // is the rail itself; swipe-back is for nested setup only.
                let skip_edge = {
                    let st = app_state().lock().unwrap();
                    let unlocked = !matches!(
                        st.screen,
                        Screen::Lock | Screen::DeviceSetup | Screen::Onboard | Screen::ClientPair
                    );
                    unlocked && self.window_inner_width(cx) >= store::TABLET_SHELL_BREAKPOINT_CSS
                };
                let width = self.window_inner_width(cx);
                let mut origin = mouse_swipe_origin().lock().unwrap();
                if skip_edge {
                    *origin = None;
                } else if e.abs.x < 48.0 {
                    *origin = Some((e.abs, SwipeNav::Back));
                } else if e.abs.x > width - 48.0 {
                    *origin = Some((e.abs, SwipeNav::Forward));
                } else {
                    *origin = None;
                }
                false
            }
            Event::MouseUp(e) if e.button.is_primary() => {
                let start_edge = mouse_swipe_origin().lock().unwrap().take();
                match start_edge {
                    Some((start, edge)) => self.edge_swipe_nav(cx, start, e.abs, edge),
                    None => false,
                }
            }
            Event::TouchUpdate(e) => {
                let width = self.window_inner_width(cx);
                let mut origin = swipe_origin().lock().unwrap();
                let mut nav: Option<SwipeNav> = None;
                let mut start_end: Option<(DVec2, DVec2)> = None;
                for touch in &e.touches {
                    match touch.state {
                        TouchState::Start => {
                            if touch.abs.x < 48.0 {
                                *origin = Some((touch.uid, touch.abs, SwipeNav::Back));
                            } else if touch.abs.x > width - 48.0 {
                                *origin = Some((touch.uid, touch.abs, SwipeNav::Forward));
                            }
                        }
                        TouchState::Stop => {
                            if let Some((uid, start, edge)) = *origin
                                && uid == touch.uid
                            {
                                start_end = Some((start, touch.abs));
                                nav = Some(edge);
                                *origin = None;
                            }
                        }
                        _ => {}
                    }
                }
                drop(origin);
                match (nav, start_end) {
                    (Some(edge), Some((start, end))) => self.edge_swipe_nav(cx, start, end, edge),
                    _ => false,
                }
            }
            _ => false,
        };
        if navigated {
            // Claim the gesture slot so a paired XF86Back key doesn't step twice.
            let _ = nav_gesture_ok();
            true
        } else {
            false
        }
    }

    fn resolve_data_base(&mut self, cx: &mut Cx) {
        let mut st = app_state().lock().unwrap();
        if st.data_base.is_none() {
            if let Some(dir) = cx.get_data_dir() {
                print_share::use_device_dir(std::path::Path::new(&dir));
                st.data_base = Some(PathBuf::from(dir));
            } else if let Ok(dir) = store::data_dir() {
                print_share::use_device_dir(&dir);
                st.data_base = Some(dir);
            }
        }
    }

    fn persist_setup_language(st: &mut AppState) {
        let follow = st.language_follow_platform;
        let code = st.locale.language.clone();
        if let Some(store) = st.store.as_ref() {
            let persisted = if follow {
                store.set_platform_language()
            } else {
                store.set_user_language(&code)
            };
            if let Ok(loc) = persisted {
                st.locale = loc;
            }
            st.save_remembered_language();
        }
    }

    /// Server Mode: create the first local server, or show create/pick when several exist.
    fn begin_server_mode(&mut self, cx: &mut Cx) {
        self.resolve_data_base(cx);
        let result = (|| -> Result<(), String> {
            let mut st = app_state().lock().unwrap();
            st.refresh_local_servers()?;
            if st.local_servers.is_empty() {
                drop(st);
                self.activate_new_server(cx, "")?;
            } else {
                st.picking_server = true;
                st.status = st.t("choose_server");
            }
            Ok(())
        })();
        if let Err(e) = result {
            self.set_status(cx, e);
        }
        self.sync_chrome(cx);
    }

    fn activate_new_server(&mut self, cx: &mut Cx, name: &str) -> Result<(), String> {
        self.resolve_data_base(cx);
        let base = {
            let st = app_state().lock().unwrap();
            st.data_base
                .clone()
                .ok_or_else(|| "No data directory".to_string())?
        };
        net::stop_server();
        let (_info, store) = local_servers::create_local_server(&base, name)?;
        {
            let mut st = app_state().lock().unwrap();
            st.store = Some(store);
            st.picking_server = false;
            let _ = st.refresh_local_servers();
            // Language is app-global: keep the choice showing on DeviceSetup
            // across the reload (which reads the new shop's own meta).
            let chosen = (st.language_follow_platform, st.locale.language.clone());
            let _ = st.reload_all();
            st.language_follow_platform = chosen.0;
            st.locale.language = chosen.1;
            Self::persist_setup_language(&mut st);
            self.finish_as_server(&mut st, true);
        }
        self.sync_chrome(cx);
        Ok(())
    }

    fn activate_existing_server(&mut self, cx: &mut Cx, server_id: &str) -> Result<(), String> {
        self.resolve_data_base(cx);
        let base = {
            let st = app_state().lock().unwrap();
            st.data_base
                .clone()
                .ok_or_else(|| "No data directory".to_string())?
        };
        net::stop_server();
        let store = local_servers::open_server(&base, server_id)?;
        {
            let mut st = app_state().lock().unwrap();
            let previous = st.device_role;
            st.store = Some(store);
            st.picking_server = false;
            let _ = st.refresh_local_servers();
            // Language is app-global: keep the choice showing on DeviceSetup
            // across the reload (which reads this shop's own meta).
            let chosen = (st.language_follow_platform, st.locale.language.clone());
            let _ = st.reload_all();
            st.language_follow_platform = chosen.0;
            st.locale.language = chosen.1;
            Self::persist_setup_language(&mut st);
            self.finish_as_server(&mut st, previous != DeviceRole::Server);
        }
        self.sync_chrome(cx);
        Ok(())
    }

    fn finish_as_server(&mut self, st: &mut AppState, switching_in: bool) {
        st.device_role = DeviceRole::Server;
        st.must_confirm_device_role = false;
        st.picking_server = false;
        st.lock_as_owner = true;
        st.pin_buffer.clear();
        st.nav_back.clear();
        st.nav_forward.clear();
        if let Some(store) = st.store.as_ref() {
            let _ = store.set_device_role(DeviceRole::Server.as_str());
            if switching_in {
                let _ = store.set_extra_tills_allowed(false);
                st.extra_tills_allowed = false;
                net::stop_server();
            } else if st.extra_tills_allowed {
                let path = store.db_path().to_path_buf();
                if net::ensure_server(path).is_ok() {
                    firewall_job(|| Ok(net::firewall_allows_phones()));
                }
            }
        }
        st.screen = Screen::Lock;
        st.status = if !st.owner_setup_complete {
            locale::t(&st.locale.language, "status_server_set_pin")
        } else if st.extra_tills_allowed {
            locale::t(&st.locale.language, "status_server_tills")
        } else {
            locale::t(&st.locale.language, "status_server_unlock")
        };
    }

    fn begin_client_mode(&mut self, cx: &mut Cx) {
        self.resolve_data_base(cx);
        let result = (|| -> Result<(), String> {
            let base = {
                let st = app_state().lock().unwrap();
                st.data_base
                    .clone()
                    .ok_or_else(|| "No data directory".to_string())?
            };
            net::stop_server();
            let store = local_servers::open_client_store(&base)?;
            let mut st = app_state().lock().unwrap();
            st.store = Some(store);
            st.picking_server = false;
            // Language is app-global: keep the choice showing on DeviceSetup
            // across the reload (which reads the client cache's own meta).
            let chosen = (st.language_follow_platform, st.locale.language.clone());
            let _ = st.reload_all();
            st.language_follow_platform = chosen.0;
            st.locale.language = chosen.1;
            Self::persist_setup_language(&mut st);
            let store = st.store.as_ref().ok_or_else(|| "No store".to_string())?;
            store.prepare_as_client_terminal()?;
            // Saved like Server Mode is: a reload (pairing, sync) reads the
            // role back from the store and must not find it unset.
            store.set_device_role(DeviceRole::Client.as_str())?;
            st.device_role = DeviceRole::Client;
            st.must_confirm_device_role = false;
            st.owner_setup_complete = true;
            st.onboarding_complete = true;
            st.extra_tills_allowed = false;
            st.lock_as_owner = true;
            st.pin_buffer.clear();
            st.nav_back.clear();
            st.nav_forward.clear();
            let _ = st.reload_all();
            st.client_paired = store_client_paired(st.store.as_ref());
            if st.staff.iter().any(|s| !s.is_owner()) {
                st.lock_as_owner = false;
                if st.lock_staff_id.is_none() {
                    st.lock_staff_id = st
                        .staff
                        .iter()
                        .find(|s| !s.is_owner())
                        .map(|s| s.id.clone());
                }
            }
            if st.client_paired {
                st.screen = Screen::Lock;
                st.status = locale::t(&st.locale.language, "status_client_unlock");
            } else {
                st.screen = Screen::ClientPair;
                st.status = "Client Mode — pair to the Server before selling".into();
            }
            Ok(())
        })();
        if let Err(e) = result {
            self.set_status(cx, e);
        }
        self.sync_chrome(cx);
    }

    fn set_extra_tills(&mut self, cx: &mut Cx, allowed: bool) {
        self.ensure_store(cx);
        let err = {
            let mut st = app_state().lock().unwrap();
            if let Err(e) = st.require_server_role("Change extra tills") {
                Some(e)
            } else if st.store.is_none() {
                Some("Storage not ready".into())
            } else if let Err(e) = st.store.as_ref().unwrap().set_extra_tills_allowed(allowed) {
                Some(e)
            } else {
                st.extra_tills_allowed = allowed;
                if allowed {
                    let store = st.store.as_ref().unwrap();
                    let code = store.ensure_server_pairing_code().unwrap_or_default();
                    let path = store.db_path().to_path_buf();
                    if let Err(e) = net::ensure_server(path) {
                        st.status = format!("Extra tills on, LAN listen failed: {e}");
                    } else {
                        st.status = format!("Extra tills on · pairing code {code}");
                        firewall_job(|| Ok(net::firewall_allows_phones()));
                    }
                } else {
                    net::stop_server();
                    st.status = "Extra tills off — this device still holds the shop books".into();
                }
                None
            }
        };
        if let Some(e) = err {
            self.set_status(cx, e);
        }
        self.sync_chrome(cx);
    }

    fn pin_digit(&mut self, cx: &mut Cx, d: char) {
        {
            let mut st = app_state().lock().unwrap();
            if st.pin_buffer.len() < 12 {
                st.pin_buffer.push(d);
            }
            // Clear prior unlock error once the user starts typing again.
            if st.status.starts_with("Wrong")
                || st.status.starts_with("Enter at least")
                || st.status.starts_with("Storage")
                || st.status.starts_with("Add staff")
            {
                st.status.clear();
            }
        }
        self.sync_chrome(cx);
    }

    fn pin_backspace(&mut self, cx: &mut Cx) {
        {
            let mut st = app_state().lock().unwrap();
            st.pin_buffer.pop();
            if st.status.starts_with("Wrong")
                || st.status.starts_with("Enter at least")
                || st.status.starts_with("Storage")
                || st.status.starts_with("Add staff")
            {
                st.status.clear();
            }
        }
        self.sync_chrome(cx);
    }

    /// Map physical / numpad keys to a PIN digit. Only plain digit keys — no
    /// Shift/Ctrl/Alt chords.
    fn pin_key_digit(e: &KeyEvent) -> Option<char> {
        if e.modifiers.control || e.modifiers.alt || e.modifiers.logo || e.modifiers.shift {
            return None;
        }
        Some(match e.key_code {
            KeyCode::Key0 | KeyCode::Numpad0 => '0',
            KeyCode::Key1 | KeyCode::Numpad1 => '1',
            KeyCode::Key2 | KeyCode::Numpad2 => '2',
            KeyCode::Key3 | KeyCode::Numpad3 => '3',
            KeyCode::Key4 | KeyCode::Numpad4 => '4',
            KeyCode::Key5 | KeyCode::Numpad5 => '5',
            KeyCode::Key6 | KeyCode::Numpad6 => '6',
            KeyCode::Key7 | KeyCode::Numpad7 => '7',
            KeyCode::Key8 | KeyCode::Numpad8 => '8',
            KeyCode::Key9 | KeyCode::Numpad9 => '9',
            _ => return None,
        })
    }

    /// Seconds left on the wrong-PIN block, or None when unlock may proceed.
    fn unlock_block_remaining(&self) -> Option<u64> {
        let mut st = app_state().lock().unwrap();
        let until = st.unlock_blocked_until?;
        match until.checked_duration_since(std::time::Instant::now()) {
            Some(left) => Some(left.as_secs() + 1),
            None => {
                st.unlock_blocked_until = None;
                None
            }
        }
    }

    /// What the device's LAN threads brought back: pairing, sign-in, the
    /// Server's answers to writes, fresh books.
    fn take_lan_answers(&mut self, cx: &mut Cx) {
        let once = lan_once().lock().unwrap().take();
        match once {
            Some(LanOnce::SignIn {
                staff_id,
                pin,
                reply,
            }) => self.finish_lan_sign_in(cx, staff_id, pin, reply),
            Some(LanOnce::Paired(reply)) => {
                let result = (|| -> Result<String, String> {
                    let (link, snap) = reply?;
                    let mut st = app_state().lock().unwrap();
                    let store = st.store.as_ref().ok_or_else(|| "No store".to_string())?;
                    store.set_client_device_pairing(&link.base, &link.device)?;
                    // Kept to find the Server again if its address changes.
                    store.set_paired_server_id(&link.server_id)?;
                    phone::forget_revision();
                    net::apply_snapshot(store, &snap)?;
                    phone::start(store.db_path().to_path_buf());
                    st.client_paired = true;
                    st.reload_all()?;
                    // The person signs in with their office PIN: this device's
                    // own sign-in is not one the Server knows.
                    st.session = None;
                    st.screen = Screen::Lock;
                    // The office's name as it saved it; unnamed, "the office".
                    let name = [snap.venue_title.trim(), snap.org_name.trim()]
                        .into_iter()
                        .find(|n| !n.is_empty())
                        .unwrap_or("the office")
                        .to_string();
                    Ok(format!("Paired with {name} — sign in with your office PIN"))
                })();
                match result {
                    Ok(msg) => {
                        app_state().lock().unwrap().pair_note.clear();
                        self.set_status(cx, msg)
                    }
                    Err(e) => {
                        app_state().lock().unwrap().pair_note = e.clone();
                        self.set_status(cx, e)
                    }
                }
                self.sync_chrome(cx);
            }
            None => {}
        }
        // The office forgot this device (Forget on the Server): back to
        // pairing, saying why. Waiting bookings stay on the device for after.
        let forgotten = {
            let mut st = app_state().lock().unwrap();
            if st.device_role == DeviceRole::Client
                && st.client_paired
                && phone::link_state().needs_pairing
            {
                st.client_paired = false;
                if let Some(store) = st.store.as_ref() {
                    let _ = store.clear_client_pairing();
                }
                st.session = None;
                st.pair_note = st.t("device_forgotten");
                st.screen = Screen::ClientPair;
                true
            } else {
                false
            }
        };
        let answers = phone::take_done();
        let synced = phone::take_synced();
        if answers.is_empty() && !synced {
            // The header's link line may have changed (offline, waiting).
            self.sync_chrome(cx);
            return;
        }
        let _ = forgotten;
        let mut snack = None;
        let mut said = None;
        {
            let mut st = app_state().lock().unwrap();
            for answer in answers {
                match answer.reply {
                    Err(e) => {
                        // The Server's own words, said about what it was.
                        said = Some(if e.is_offline() {
                            format!("{} — {e}", answer.label)
                        } else {
                            format!("{}: {e}", answer.label)
                        });
                        if e.code() == "pair_again" {
                            st.client_paired = false;
                        }
                    }
                    Ok(reply) => {
                        said = Some(answer.done.clone());
                        if answer.follow == phone::Follow::Sale
                            && let Ok(sale) = serde_json::from_value::<Sale>(reply)
                        {
                            st.last_awb = sale.awb_no.clone();
                            said = Some(if sale.awb_no.is_empty() {
                                format!("Booked · {}", answer.done)
                            } else {
                                format!("Booked · AWB {} · {}", sale.awb_no, answer.done)
                            });
                            snack = Some((sale.id, answer.done));
                        }
                    }
                }
            }
            if synced {
                let _ = st.reload_all();
            }
        }
        if let Some(msg) = said {
            self.set_status(cx, msg);
        }
        if let Some((sale_id, _)) = &snack {
            // A booking's own receipt beats the status on the receipt line.
            let mut st = app_state().lock().unwrap();
            if let Some(text) = st
                .store
                .as_ref()
                .and_then(|s| s.format_receipt_text(sale_id).ok())
            {
                st.last_receipt = text;
            }
        }
        if let Some((sale_id, text)) = snack {
            self.show_undo_snackbar(cx, sale_id, text);
        }
        self.sync_chrome(cx);
    }

    fn show_found_servers(&mut self, cx: &mut Cx, found: Vec<net::FoundServer>) {
        let (text, rows) = {
            let mut st = app_state().lock().unwrap();
            let text = if found.is_empty() { st.t("no_server_found") } else { String::new() };
            // One row per office found: its name, and the address.
            let rows = found
                .iter()
                .map(|f| {
                    let venue = if f.venue.trim().is_empty() {
                        "Moklanjo"
                    } else {
                        f.venue.trim()
                    };
                    ReportRow::Kv(venue.to_string(), f.host.clone())
                })
                .collect::<Vec<_>>();
            st.found_servers = found;
            (text, rows)
        };
        let first = app_state()
            .lock()
            .unwrap()
            .found_servers
            .first()
            .map(|f| f.host.clone());
        if let Some(host) = first {
            self.ui
                .text_input(cx, ids!(client_host_input))
                .set_text(cx, &host);
        }
        self.ui
            .widget(cx, ids!(client_found_label))
            .set_text(cx, &plain_display_text(&text));
        self.ui.widget(cx, ids!(client_found_label)).set_visible(cx, !text.is_empty());
        self.set_report_rows(cx, ids!(client_found_list), rows);
        self.sync_chrome(cx);
    }

    fn try_unlock(&mut self, cx: &mut Cx) {
        self.ensure_store(cx);
        {
            let st = app_state().lock().unwrap();
            if st.must_confirm_device_role || st.device_role == DeviceRole::Unset {
                drop(st);
                self.go(cx, Screen::DeviceSetup);
                return;
            }
        }
        let (pin, lock_as_owner, lock_staff_id, has_store, owner_setup_complete, pin_reset) = {
            let st = app_state().lock().unwrap();
            (
                st.pin_buffer.clone(),
                st.lock_as_owner,
                st.lock_staff_id.clone(),
                st.store.is_some(),
                st.owner_setup_complete,
                st.pin_reset_required,
            )
        };
        if !has_store {
            self.set_status(cx, "Storage not ready — restart the app");
            return;
        }
        // Too many wrong PINs: sit out the block before trying again.
        if let Some(left) = self.unlock_block_remaining() {
            self.set_status(
                cx,
                format!("Too many wrong PINs — wait {left}s, then try again"),
            );
            return;
        }
        if pin.len() < 4 {
            self.set_status(cx, "Enter at least 4 digits, then OK");
            return;
        }

        // First-run Owner PIN setup (Server shop UX).
        if !owner_setup_complete {
            let result = (|| -> Result<(), String> {
                let mut st = app_state().lock().unwrap();
                let store = st.store.as_ref().ok_or_else(|| "No store".to_string())?;
                let member = store.complete_owner_setup(&pin)?;
                let _ = store.set_active_session_staff_id(Some(&member.id));
                st.owner_setup_complete = true;
                st.onboarding_complete = false;
                st.onboard_step = 1;
                st.session = Some(member);
                st.pin_buffer.clear();
                st.pin_visible = false;
                st.lock_as_owner = true;
                st.screen = Screen::Onboard;
                st.status = "Owner ready — set up your shop".into();
                let _ = st.reload_all();
                Ok(())
            })();
            match result {
                Ok(()) => log!("Kumkaj owner setup ok"),
                Err(ref e) => {
                    log!("Kumkaj owner setup failed: {e}");
                    let mut st = app_state().lock().unwrap();
                    st.pin_buffer.clear();
                    st.pin_visible = false;
                    drop(st);
                    self.set_status(cx, e.clone());
                }
            }
            self.sync_chrome(cx);
            return;
        }

        // The upgrade that replaced the PIN hasher handed every account back as
        // 0000. Reuse the first-run setup flow to get a real Owner PIN before
        // the till opens.
        if pin_reset {
            let result = (|| -> Result<(), String> {
                let mut st = app_state().lock().unwrap();
                let store = st.store.as_ref().ok_or_else(|| "No store".to_string())?;
                let member = store.complete_pin_reset(&pin)?;
                let _ = store.set_active_session_staff_id(Some(&member.id));
                st.session = Some(member.clone());
                st.pin_buffer.clear();
                st.pin_visible = false;
                st.lock_as_owner = true;
                st.failed_unlocks = 0;
                st.screen = unlocked_home();
                st.status = format!("New Owner PIN set — welcome back, {}", member.lock_label());
                let _ = st.refresh_books_overview();
                let _ = st.reload_all();
                Ok(())
            })();
            match result {
                Ok(()) => log!("Kumkaj owner PIN reset ok"),
                Err(ref e) => {
                    log!("Kumkaj owner PIN reset failed: {e}");
                    let mut st = app_state().lock().unwrap();
                    st.pin_buffer.clear();
                    st.pin_visible = false;
                    drop(st);
                    self.set_status(cx, e.clone());
                }
            }
            self.sync_chrome(cx);
            return;
        }

        // A paired device signs in on the Server (PINs are checked there,
        // never on the device), off the UI thread.
        let lan = {
            let st = app_state().lock().unwrap();
            let staff_id = if lock_as_owner {
                None
            } else {
                lock_staff_id.clone().or_else(|| {
                    st.staff
                        .iter()
                        .find(|s| !s.is_owner())
                        .map(|s| s.id.clone())
                })
            };
            let link = (st.device_role == DeviceRole::Client && st.client_paired)
                .then(|| {
                    st.store.as_ref().and_then(|s| {
                        Some(net::Link {
                            base: s.server_url().ok()??,
                            device: s.client_device_token().ok()??,
                            ..net::Link::default()
                        })
                    })
                })
                .flatten();
            link.map(|link| (link, staff_id))
        };
        if let Some((link, staff_id)) = lan {
            {
                let mut st = app_state().lock().unwrap();
                if st.lan_sign_in_busy {
                    return;
                }
                st.lan_sign_in_busy = true;
                st.status = "Checking your PIN with the shop…".into();
            }
            let pin = pin.clone();
            let _ = std::thread::Builder::new()
                .name("moklanjo-sign-in".into())
                .spawn(move || {
                    let reply = net::client_login(&link, staff_id.as_deref(), &pin);
                    *lan_once().lock().unwrap() = Some(LanOnce::SignIn {
                        staff_id,
                        pin,
                        reply,
                    });
                    makepad_widgets::makepad_platform::thread::SignalToUI::set_ui_signal();
                });
            self.sync_chrome(cx);
            return;
        }

        // Auth runs without holding the app mutex (PIN verify must not freeze the UI).
        // Emergency unlock PIN is checked first (wipe + open as Owner, looks normal).
        let auth = {
            let st = app_state().lock().unwrap();
            match st.store.as_ref() {
                Some(store) => {
                    if let Ok(Some(owner)) = store.try_duress_unlock(&pin) {
                        Ok(Some(owner))
                    } else if lock_as_owner {
                        store.authenticate_owner_pin(&pin)
                    } else {
                        let staff_id = lock_staff_id.clone().or_else(|| {
                            st.staff
                                .iter()
                                .find(|s| !s.is_owner())
                                .map(|s| s.id.clone())
                        });
                        match staff_id {
                            Some(id) => store.authenticate_staff_pin(&id, &pin),
                            None => Ok(None),
                        }
                    }
                }
                None => Err("No store".into()),
            }
        };
        self.finish_unlock(cx, auth, lock_as_owner, None);
    }

    /// The Server's answer to a device's sign-in. Out of reach: whoever last
    /// signed in on this device may unlock with the session saved then.
    fn finish_lan_sign_in(
        &mut self,
        cx: &mut Cx,
        staff_id: Option<String>,
        pin: String,
        reply: Result<net::LoginOk, net::LanError>,
    ) {
        let lock_as_owner = staff_id.is_none();
        let (auth, note) = {
            let mut st = app_state().lock().unwrap();
            st.lan_sign_in_busy = false;
            let Some(store) = st.store.as_ref() else {
                return;
            };
            match reply {
                Ok(ok) => {
                    let saved = store.remember_lan_sign_in(&ok.staff, &pin, &ok.session);
                    phone::signed_in();
                    (saved.map(|()| Some(ok.staff)), None)
                }
                Err(e) if e.is_offline() => {
                    match store.offline_lan_sign_in(staff_id.as_deref(), &pin) {
                        Ok(Some((staff, _))) => (
                            Ok(Some(staff)),
                            Some(
                                "Offline — orders wait on this device until the Wi‑Fi is back"
                                    .to_string(),
                            ),
                        ),
                        Ok(None) => (
                            Err(format!(
                                "{e} — and this person has not signed in on this device before"
                            )),
                            None,
                        ),
                        Err(err) => (Err(err), None),
                    }
                }
                Err(e) if e.code() == "wrong_pin" => (Ok(None), None),
                Err(e) if e.code() == "pair_again" => {
                    // Forgotten by the shop: pair again, and say why.
                    let _ = store.clear_client_pairing();
                    st.client_paired = false;
                    st.pair_note = st.t("device_forgotten");
                    st.screen = Screen::ClientPair;
                    (Err(st.pair_note.clone()), None)
                }
                Err(e) => (Err(e.to_string()), None),
            }
        };
        self.finish_unlock(cx, auth, lock_as_owner, note);
    }

    fn finish_unlock(
        &mut self,
        cx: &mut Cx,
        auth: Result<Option<StaffMember>, String>,
        lock_as_owner: bool,
        note: Option<String>,
    ) {
        let result = {
            let mut st = app_state().lock().unwrap();
            if !st.lock_as_owner && st.lock_staff_id.is_none() {
                st.lock_staff_id = st
                    .staff
                    .iter()
                    .find(|s| !s.is_owner())
                    .map(|s| s.id.clone());
            }
            match auth {
                Ok(Some(member)) => {
                    if let Some(store) = st.store.as_ref() {
                        let _ = store.set_active_session_staff_id(Some(&member.id));
                    }
                    st.session = Some(member.clone());
                    st.pin_buffer.clear();
                    st.pin_visible = false;
                    st.failed_unlocks = 0;
                    st.unlock_blocked_until = None;
                    if st.device_role == DeviceRole::Client && !st.client_paired {
                        st.screen = Screen::ClientPair;
                        st.status = "Pair to the shop device before selling".into();
                    } else if st.device_role.is_host() && !st.onboarding_complete {
                        st.screen = Screen::Onboard;
                        st.status = format!("Welcome, {} — finish shop setup", member.lock_label());
                    } else {
                        st.screen = unlocked_home();
                        st.status = match &note {
                            Some(note) => format!("Welcome, {} · {note}", member.lock_label()),
                            None => format!("Welcome, {}", member.lock_label()),
                        };
                        let _ = st.refresh_books_overview();
                    }
                    if st.device_role == DeviceRole::Client
                        && st.client_paired
                        && let Some(store) = st.store.as_ref()
                    {
                        phone::start(store.db_path().to_path_buf());
                    }
                    // The books live here: back them up every day.
                    if st.device_role.is_host()
                        && let Some(store) = st.store.as_ref()
                    {
                        start_auto_backups(store.db_path().to_path_buf());
                    }
                    if st.uses_lan()
                        && let Some(store) = st.store.as_ref()
                    {
                        let path = store.db_path().to_path_buf();
                        if net::ensure_server(path).is_ok() {
                            firewall_job(|| Ok(net::firewall_allows_phones()));
                        }
                    }
                    Ok(())
                }
                Ok(None) => {
                    st.pin_buffer.clear();
                    st.pin_visible = false;
                    st.failed_unlocks = st.failed_unlocks.saturating_add(1);
                    if st.failed_unlocks >= UNLOCK_ATTEMPT_LIMIT {
                        st.failed_unlocks = 0;
                        st.unlock_blocked_until = Some(std::time::Instant::now() + UNLOCK_BLOCK);
                        Err(format!(
                            "Too many wrong PINs — locked for {}s",
                            UNLOCK_BLOCK.as_secs()
                        ))
                    } else {
                        let left = UNLOCK_ATTEMPT_LIMIT - st.failed_unlocks;
                        Err(if lock_as_owner {
                            format!("Wrong Owner PIN — {left} tries left")
                        } else if st.lock_staff_id.is_none() {
                            "Add staff in Team first, or unlock as Owner".into()
                        } else {
                            format!("Wrong Staff PIN — {left} tries left")
                        })
                    }
                }
                Err(e) => Err(e),
            }
        };
        match result {
            Ok(()) => log!("Kumkaj unlock ok"),
            Err(ref e) => log!("Kumkaj unlock failed: {e}"),
        }
        match result {
            Ok(()) => {}
            Err(e) => self.set_status(cx, e),
        }
        self.sync_chrome(cx);
    }

